{"command": "cd /workspace/queue/posts; python3 -c "
import json,glob
for f in sorted(glob.glob('*.jsonl')):
    cid=f[:-6]
    print('='*70)
    print('CASE',cid)
    for line in open(f):
        line=line.strip()
        if not line: continue
        d=json.loads(line)
        print('[%s] %s | %s | %s' % (d['post_id'], d['date'], d['platform'], d.get('handle','')))
        print('   ', d['text'].replace(chr(10),' '))
        if d.get('engagement'): print('    eng:', d['engagement'])
        for k,v in d.items():
            if k not in ('post_id','date','platform','handle','text','engagement'):
                print('    EXTRA %s: %s' % (k,v))
" > /workspace/out/_all_posts.txt; wc -l /workspace/out/_all_posts.txt; sed -n '1,120p' /workspace/out/_all_posts.txt"}

